<?php
namespace App\Http\Controllers;
use Illuminate\Http\Request;use Illuminate\Support\Facades\DB;
class AcademicOfficeController extends Controller{
 private function ok(Request $r){abort_unless($r->user()->isSuperAdmin()||$r->user()->hasRole('admin')||$r->user()->hasRole('academic_head')||$r->user()->canDo('students.manage'),403);}
 public function index(Request $r){$this->ok($r);$p=$r->attributes->get('academic_period');$groups=DB::table('study_groups')->where('active',1)->orderBy('name')->get();$students=DB::table('students')->where('status','active')->orderBy('last_name')->get();$news=DB::table('group_news as n')->leftJoin('study_groups as g','g.id','=','n.study_group_id')->where('n.academic_period_id',$p->id)->select('n.*','g.name as group_name')->orderByDesc('n.id')->limit(20)->get();$activities=DB::table('activities')->where('academic_period_id',$p->id)->orderByDesc('starts_at')->limit(20)->get();$practices=DB::table('practice_placements as x')->join('students as s','s.id','=','x.student_id')->where('x.academic_period_id',$p->id)->select('x.*',DB::raw("s.last_name||' '||s.first_name as student_name"))->orderByDesc('x.id')->limit(30)->get();$orders=DB::table('student_orders')->where('academic_period_id',$p->id)->orderByDesc('order_date')->limit(30)->get();return view('academic-office.index',compact('p','groups','students','news','activities','practices','orders'));}
 public function news(Request $r){$this->ok($r);$p=$r->attributes->get('academic_period');$d=$r->validate(['study_group_id'=>'nullable|exists:study_groups,id','title'=>'required|string|max:255','body'=>'required|string|max:10000','pinned'=>'nullable|boolean']);DB::table('group_news')->insert(array_merge($d,['academic_period_id'=>$p->id,'author_id'=>$r->user()->id,'pinned'=>$r->boolean('pinned'),'published_at'=>now(),'created_at'=>now(),'updated_at'=>now()]));return back()->with('success','Новость опубликована.');}
 public function activity(Request $r){$this->ok($r);$p=$r->attributes->get('academic_period');$d=$r->validate(['study_group_id'=>'nullable|exists:study_groups,id','title'=>'required|string|max:255','description'=>'nullable|string|max:10000','location'=>'nullable|string|max:255','starts_at'=>'required|date','ends_at'=>'nullable|date|after_or_equal:starts_at','registration_until'=>'nullable|date','capacity'=>'nullable|integer|min:1|max:10000']);DB::table('activities')->insert(array_merge($d,['academic_period_id'=>$p->id,'created_by'=>$r->user()->id,'status'=>'open','created_at'=>now(),'updated_at'=>now()]));return back()->with('success','Активность создана.');}
 public function practice(Request $r){$this->ok($r);$p=$r->attributes->get('academic_period');$d=$r->validate(['student_id'=>'required|exists:students,id','practice_type'=>'required|string|max:255','organization_name'=>'required|string|max:500','organization_address'=>'nullable|string|max:500','supervisor_org'=>'nullable|string|max:255','supervisor_teacher_id'=>'nullable|exists:teachers,id','starts_on'=>'required|date','ends_on'=>'required|date|after_or_equal:starts_on','order_number'=>'nullable|string|max:100','order_date'=>'nullable|date']);DB::table('practice_placements')->insert(array_merge($d,['academic_period_id'=>$p->id,'status'=>'planned','created_at'=>now(),'updated_at'=>now()]));return back()->with('success','Практика назначена.');}
 public function practiceResult(Request $r,$practice){$this->ok($r);$d=$r->validate(['status'=>'required|in:planned,in_progress,completed,failed','result'=>'nullable|string|max:100','comment'=>'nullable|string|max:5000']);DB::table('practice_placements')->where('id',$practice)->update(array_merge($d,['updated_at'=>now()]));return back()->with('success','Практика обновлена.');}
 public function order(Request $r){$this->ok($r);$p=$r->attributes->get('academic_period');$d=$r->validate(['student_id'=>'nullable|exists:students,id','number'=>'required|string|max:100','order_date'=>'required|date','type'=>'required|string|max:100','title'=>'required|string|max:500','basis'=>'nullable|string|max:5000']);DB::table('student_orders')->insert(array_merge($d,['academic_period_id'=>$p->id,'created_by'=>$r->user()->id,'status'=>'registered','created_at'=>now(),'updated_at'=>now()]));return back()->with('success','Приказ зарегистрирован.');}
}